// HealthAndDamageComponent.cpp — matching implementation
#include "HealthAndDamageComponent.h"
#include "TimerManager.h"

UHealthAndDamageComponent::UHealthAndDamageComponent()
{
	PrimaryComponentTick.bCanEverTick = false;
	MaxHealth = 100.0f;
	CurrentHealth = 100.0f;
	HealTickRate = 1.0f;
	bIsDead = false;
	TargetHealAmount = 0.0f;
	HealTickInterval = 0.0f;
}

void UHealthAndDamageComponent::BeginPlay()
{
	Super::BeginPlay();
	CurrentHealth = FMath::Clamp(CurrentHealth, 0.0f, MaxHealth);
}

void UHealthAndDamageComponent::ApplyDamage(float DamageAmount)
{
	if (bIsDead || DamageAmount <= 0.0f)
	{
		return;
	}

	CurrentHealth = FMath::Clamp(CurrentHealth - DamageAmount, 0.0f, MaxHealth);
	OnHealthChanged.Broadcast(CurrentHealth);

	if (CurrentHealth <= 0.0f && !bIsDead)
	{
		bIsDead = true;
		OnDeath.Broadcast();
	}
}

void UHealthAndDamageComponent::ApplyHeal(float HealAmount, float Duration)
{
	if (bIsDead || HealAmount <= 0.0f)
	{
		return;
	}

	TargetHealAmount = HealAmount;
	if (Duration <= 0.0f)
	{
		CurrentHealth = FMath::Clamp(CurrentHealth + HealAmount, 0.0f, MaxHealth);
		OnHealthChanged.Broadcast(CurrentHealth);
		return;
	}

	int32 NumTicks = FMath::Max(1, FMath::RoundToInt(Duration / HealTickRate));
	HealTickInterval = HealAmount / static_cast<float>(NumTicks);

	GetWorld()->GetTimerManager().SetTimer(HealTimerHandle, this, &UHealthAndDamageComponent::ExecuteHealTick, HealTickRate, true);
}

void UHealthAndDamageComponent::ExecuteHealTick()
{
	if (bIsDead || CurrentHealth >= MaxHealth)
	{
		GetWorld()->GetTimerManager().ClearTimer(HealTimerHandle);
		return;
	}

	CurrentHealth = FMath::Clamp(CurrentHealth + HealTickInterval, 0.0f, MaxHealth);
	TargetHealAmount -= HealTickInterval;
	OnHealthChanged.Broadcast(CurrentHealth);

	if (TargetHealAmount <= 0.0f || CurrentHealth >= MaxHealth)
	{
		GetWorld()->GetTimerManager().ClearTimer(HealTimerHandle);
	}
}

