// ReplicatedHealthComponent.cpp — matching implementation
#include "ReplicatedHealthComponent.h"
#include "Net/UnrealNetwork.h"
#include "TimerManager.h"

UReplicatedHealthComponent::UReplicatedHealthComponent()
{
	PrimaryComponentTick.bCanEverTick = false;
	SetIsReplicatedByDefault(true);
	MaxHealth = 200.0f;
	CurrentHealth = 200.0f;
	ShieldAmount = 50.0f;
	HealTickRate = 1.0f;
	TargetHealAmount = 0.0f;
	HealTickInterval = 0.0f;
}

void UReplicatedHealthComponent::GetLifetimeReplicatedProps(TArray<FLifetimeProperty>& OutLifetimeProps) const
{
	Super::GetLifetimeReplicatedProps(OutLifetimeProps);
	DOREPLIFETIME(UReplicatedHealthComponent, MaxHealth);
	DOREPLIFETIME(UReplicatedHealthComponent, CurrentHealth);
	DOREPLIFETIME(UReplicatedHealthComponent, ShieldAmount);
}

void UReplicatedHealthComponent::BeginPlay()
{
	Super::BeginPlay();
	if (GetOwner() && GetOwner()->HasAuthority())
	{
		CurrentHealth = FMath::Clamp(CurrentHealth, 0.0f, MaxHealth);
		CharacterStateTags.AddTag(FGameplayTag::RequestGameplayTag(TEXT("State.Normal")));
	}
}

void UReplicatedHealthComponent::ApplyDamage(float DamageAmount)
{
	if (!GetOwner() || !GetOwner()->HasAuthority() || DamageAmount <= 0.0f)
	{
		return;
	}

	if (CharacterStateTags.HasTag(FGameplayTag::RequestGameplayTag(TEXT("State.Dead"))))
	{
		return;
	}

	float RemainingDamage = DamageAmount;
	if (ShieldAmount > 0.0f)
	{
		if (ShieldAmount >= RemainingDamage)
		{
			ShieldAmount -= RemainingDamage;
			RemainingDamage = 0.0f;
		}
		else
		{
			RemainingDamage -= ShieldAmount;
			ShieldAmount = 0.0f;
		}
		OnShieldChanged.Broadcast(ShieldAmount);
	}

	if (RemainingDamage > 0.0f)
	{
		CurrentHealth = FMath::Clamp(CurrentHealth - RemainingDamage, 0.0f, MaxHealth);
		OnHealthChanged.Broadcast(CurrentHealth);

		if (CurrentHealth <= 0.0f)
		{
			CharacterStateTags.RemoveTag(FGameplayTag::RequestGameplayTag(TEXT("State.Normal")));
			CharacterStateTags.AddTag(FGameplayTag::RequestGameplayTag(TEXT("State.Dead")));
			OnDeath.Broadcast();
		}
	}
}

void UReplicatedHealthComponent::ApplyHeal(float HealAmount, float Duration)
{
	if (!GetOwner() || !GetOwner()->HasAuthority() || HealAmount <= 0.0f)
	{
		return;
	}

	if (CharacterStateTags.HasTag(FGameplayTag::RequestGameplayTag(TEXT("State.Dead"))))
	{
		return;
	}

	TargetHealAmount = HealAmount;
	if (Duration <= 0.0f)
	{
		CurrentHealth = FMath::Clamp(CurrentHealth + HealAmount, 0.0f, MaxHealth);
		OnHealthChanged.Broadcast(CurrentHealth);
		return;
	}

	int32 NumTicks = FMath::Max(1, FMath::RoundToInt(Duration / HealTickRate));
	HealTickInterval = HealAmount / static_cast<float>(NumTicks);

	GetWorld()->GetTimerManager().SetTimer(HealTimerHandle, this, &UReplicatedHealthComponent::ExecuteHealTick, HealTickRate, true);
}

void UReplicatedHealthComponent::ExecuteHealTick()
{
	if (CurrentHealth >= MaxHealth)
	{
		GetWorld()->GetTimerManager().ClearTimer(HealTimerHandle);
		return;
	}

	CurrentHealth = FMath::Clamp(CurrentHealth + HealTickInterval, 0.0f, MaxHealth);
	TargetHealAmount -= HealTickInterval;
	OnHealthChanged.Broadcast(CurrentHealth);

	if (TargetHealAmount <= 0.0f || CurrentHealth >= MaxHealth)
	{
		GetWorld()->GetTimerManager().ClearTimer(HealTimerHandle);
	}
}

void UReplicatedHealthComponent::OnRep_CurrentHealth()
{
	OnHealthChanged.Broadcast(CurrentHealth);
}
